-- CreateSchemaCREATE SCHEMA IF NOT EXISTS "public";-- CreateTableCREATE TABLE "User" (    "id" TEXT NOT NULL,    "email" TEXT NOT NULL,    "name" TEXT,    "username" TEXT,    "role" TEXT NOT NULL DEFAULT 'user',    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    "level" INTEGER NOT NULL DEFAULT 1,    "xp" INTEGER NOT NULL DEFAULT 0,    "reputationScore" INTEGER NOT NULL DEFAULT 0,    "lastActive" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "bio" TEXT,    "avatarUrl" TEXT,    "isVerified" BOOLEAN NOT NULL DEFAULT false,    CONSTRAINT "User_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "KnowledgeBaseArticle" (    "id" TEXT NOT NULL,    "title" TEXT NOT NULL,    "slug" TEXT NOT NULL,    "content" TEXT NOT NULL,    "summary" TEXT NOT NULL,    "category" TEXT NOT NULL,    "tags" TEXT[],    "embedding" DOUBLE PRECISION[],    "source" TEXT,    "sourceUrl" TEXT,    "author" TEXT,    "version" INTEGER NOT NULL DEFAULT 1,    "isActive" BOOLEAN NOT NULL DEFAULT true,    "viewCount" INTEGER NOT NULL DEFAULT 0,    "helpfulCount" INTEGER NOT NULL DEFAULT 0,    "unhelpfulCount" INTEGER NOT NULL DEFAULT 0,    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    "publishedAt" TIMESTAMP(3),    CONSTRAINT "KnowledgeBaseArticle_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "ArticleSection" (    "id" TEXT NOT NULL,    "articleId" TEXT NOT NULL,    "sectionNumber" INTEGER NOT NULL,    "heading" TEXT NOT NULL,    "content" TEXT NOT NULL,    "embedding" DOUBLE PRECISION[],    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "ArticleSection_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "RelatedArticle" (    "id" TEXT NOT NULL,    "articleId" TEXT NOT NULL,    "relatedId" TEXT NOT NULL,    "relevanceScore" DOUBLE PRECISION NOT NULL DEFAULT 0.5,    CONSTRAINT "RelatedArticle_pkey" PRIMARY KEY ("id")