atured" BOOLEAN NOT NULL DEFAULT false,    "imageUrl" TEXT,    "enrolledCount" INTEGER NOT NULL DEFAULT 0,    "completedCount" INTEGER NOT NULL DEFAULT 0,    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "LearningPath_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "UserLearningPath" (    "id" TEXT NOT NULL,    "userId" TEXT NOT NULL,    "learningPathId" TEXT NOT NULL,    "status" TEXT NOT NULL DEFAULT 'in_progress',    "currentModuleIndex" INTEGER NOT NULL DEFAULT 0,    "progressPercent" INTEGER NOT NULL DEFAULT 0,    "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "completedAt" TIMESTAMP(3),    "lastAccessedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "totalXpEarned" INTEGER NOT NULL DEFAULT 0,    "badgesEarned" TEXT[],    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "UserLearningPath_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "BookmarkedCourse" (    "id" TEXT NOT NULL,    "userId" TEXT NOT NULL,    "moduleId" TEXT NOT NULL,    "moduleTitle" TEXT,    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "BookmarkedCourse_pkey" PRIMARY KEY ("id"));-- CreateTableCREATE TABLE "LessonContent" (    "id" TEXT NOT NULL,    "moduleId" TEXT NOT NULL,    "lessonIndex" INTEGER NOT NULL,    "title" TEXT NOT NULL,    "content" TEXT NOT NULL,    "summary" TEXT,    "contentType" TEXT NOT NULL DEFAULT 'markdown',    "videoUrl" TEXT,    "videoDuration" INTEGER,    "hasQuiz" BOOLEAN NOT NULL DEFAULT false,    "quizData" JSONB,    "resources" JSONB,    "estimatedMinutes" INTEGER NOT NULL DEFAULT 5,    "difficulty" TEXT NOT NULL DEFAULT 'beginner',    "viewCount" INTEGER NOT NULL DEFAULT 0,    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,    "updatedAt" TIMESTAMP(3) NOT NULL,    CONSTRAINT "LessonContent_pkey" PRIMARY KEY ("id"));-- Crea